(function(root){
  const META='ikigoz-film-bytes';
  const urls=new Map();
  function fileName(id){return String(id).split('/').pop().replace(/[^a-zA-Z0-9._-]/g,'_')||'film.mp4'}
  function readMeta(){try{return JSON.parse(localStorage.getItem(META))||{}}catch{return {}}}
  function writeMeta(meta){localStorage.setItem(META,JSON.stringify(meta))}
  async function dir(){if(!navigator.storage||!navigator.storage.getDirectory){const err=new Error('Bu tarayıcı büyük dosyayı diske yazamıyor.');err.code='unsupported';throw err}return navigator.storage.getDirectory()}
  async function fileOf(id){const rootDir=await dir();const handle=await rootDir.getFileHandle(fileName(id));return handle.getFile()}
  async function has(id){try{const file=await fileOf(id);const expected=readMeta()[fileName(id)];return file.size>100000&&(!expected||file.size===expected)}catch{return false}}
  async function objectUrl(id){if(urls.has(id))return urls.get(id);try{const file=await fileOf(id);if(!(await has(id)))return null;const url=URL.createObjectURL(file);urls.set(id,url);return url}catch{return null}}
  function pieces(film){const list=film.parts&&film.parts.length?film.parts:[film.url];return list.map((url,i)=>({id:url,url,title:list.length>1?film.title+' · parça '+(i+1)+'/'+list.length:film.title}))}
  async function countReady(films){let n=0;for(const film of films){let ok=true;for(const piece of pieces(film)){if(!(await has(piece.id)))ok=false}if(ok)n++}return n}
  async function downloadOne(film,onProgress){const res=await fetch(film.url);if(!res.ok||!res.body)throw new Error('İndirilemedi');const total=Number(res.headers.get('content-length'))||0;if(navigator.storage&&navigator.storage.estimate&&total){const est=await navigator.storage.estimate();if(est.quota&&est.usage!=null&&est.usage+total>est.quota){const err=new Error('Telefonda bu film için yer yok.');err.name='QuotaExceededError';throw err}}const rootDir=await dir();const handle=await rootDir.getFileHandle(fileName(film.id),{create:true});const writable=await handle.createWritable();const reader=res.body.getReader();let got=0;try{while(true){const step=await reader.read();if(step.done)break;await writable.write(step.value);got+=step.value.byteLength;if(onProgress)onProgress(got,total)}await writable.close()}catch(err){try{await writable.abort()}catch{}throw err}const saved=await handle.getFile();if(saved.size<100000||(total&&saved.size!==total))throw new Error('Dosya eksik indi');const meta=readMeta();meta[fileName(film.id)]=saved.size;writeMeta(meta)}
  async function saveAll(films,onStatus){if(!navigator.storage||!navigator.storage.persist){const err=new Error('Bu tarayıcı kalıcı depolama izni sunmuyor.');err.code='unsupported';throw err}const granted=await navigator.storage.persist();if(!granted){const err=new Error('denied');err.code='denied';throw err}const jobs=films.flatMap(pieces);const failed=[];for(let i=0;i<jobs.length;i++){const job=jobs[i];try{if(await has(job.id)){if(onStatus)onStatus({index:i,total:jobs.length,title:job.title,skipped:true,done:true});continue}await downloadOne(job,(got,size)=>onStatus&&onStatus({index:i,total:jobs.length,title:job.title,got,size,done:false}));if(onStatus)onStatus({index:i,total:jobs.length,title:job.title,done:true})}catch(err){failed.push(job.title+': '+(err&&err.message?err.message:'kaydedilemedi'))}}if(failed.length){const err=new Error(failed.join(' · '));err.code='partial';throw err}}
  root.FilmStore={has,objectUrl,countReady,saveAll,persisted:()=>navigator.storage&&navigator.storage.persisted?navigator.storage.persisted():Promise.resolve(false)};
})(typeof globalThis!=='undefined'?globalThis:this);
